import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[2];P=ROOT/'data/processed/three_ward_urban_geometry_pair_inputs_v1';R=ROOT/'data/exp/data-preprocessing/three_ward_urban_geometry_pair_inputs_v1'
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(8*1024*1024),b''):h.update(b)
 return h.hexdigest()
def dump(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def rr(p):
 with p.open() as f:return list(csv.DictReader(f))
def table(h,rs):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in h)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in r)+'</tr>' for r in rs)+'</tbody></table></div>'
def main():
 s=json.loads((P/'preflight.json').read_text());val=json.loads((R/'validation.json').read_text());assert val['all_passed'];z=np.load(P/'paired_support_and_native_mapping.npz');vols=rr(R/'actual_encoded_pair_volumes.csv');tt=rr(R/'table_interface_summary.csv')
 fig,axes=plt.subplots(1,2,figsize=(11,7.5),sharex=True,sharey=True);extent=[-11.36,-3.66,-42.44,-32.32];active=z['Terrain Active Mask']==1
 for ax,field,title,cmap in zip(axes,[z['Roof Area']/100,z['Ground Road Area']/100],['Building footprint fraction','Classified ground-road fraction'],['magma','Blues']):
  ar=np.where(active,field,np.nan);im=ax.imshow(ar,origin='upper',extent=extent,vmin=0,vmax=1,cmap=cmap,interpolation='nearest');ax.set_title(title);ax.set_aspect('equal');ax.set_xlabel('JGD2011 / IX easting (km)');fig.colorbar(im,ax=ax,shrink=.72,label='Fraction of 10 m cell')
 axes[0].set_ylabel('JGD2011 / IX northing (km)');fig.suptitle('Urban information entering the matched comparison',fontsize=15);fig.text(.5,.015,'Inputs only. Same 10 m lattice and source terrain. White = outside land-catchment support, not zero population.',ha='center',fontsize=9);fig.tight_layout(rect=[0,.04,1,.95]);fig.savefig(R/'urban_information_support.png',dpi=160);plt.close(fig)
 # Fixed output target; no route/path claims from peak-depth-only results.
 contract={'question':'How does the existing urban geometry package change three-ward surface and transport exposure under identical forcing?','arms':['terrain_only','existing_urban_geometry_package'],'estimand':'Package sensitivity including blockage, face geometry, roughness and roof redistribution; not an isolated 3D-file-format effect.','common_grid':{'epsg':6677,'dx_m':10,'shape':[1012,770]},'common_physical_catchment_m2':s['physical_catchment_m2'],'common_open_ground_m2':s['common_open_ground_m2'],'source_terrain_file':'data/processed/three_ward_sfincs_scenarios/terrain_sampling_0_50m.tif','common_ground_support_file':'data/processed/three_ward_urban_geometry_pair_inputs_v1/paired_support_and_native_mapping.npz','main_exceedance_depths_m':[.1,.3,.5],'common_ground_comparison':'Reintegrate each arm native online peak water level over identical original fine open-ground samples. Do not directly compare solver h/hmax or give footprint terrain virtual water to U exposure labels.','masks':'Derive own run numerical masks with unchanged reference_label_policy.py; compare intersect qualified support and union quarantine, retain intervals. Do not reuse U response-dependent masks for T.','budget':'Include every interior native cell in each arm own signed storage. T footprint storage remains in T water balance. Preserve endpoint and prefix gates, no clipping.','road_exposure':'Same fixed classified ground-road support; compare affected ground area and depth, not invented road length or verified passability.','station_exposure':'Same frozen entrance points and 20m neighborhoods; retain unknown attribution; no observed ingress or shutdown claim.','corridor_paths':'Peak fields cannot establish directional flow paths. Internal cumulative face-transport interface is not qualified; defer this metric.','same_solver':'sha256:8954f37932f91a437e759213afc04769e82d7b5193e769eaa6c9df7c9c70c0a7','reference_policy_source_sha256':sha(ROOT/'src/preprocessing/reference_label_policy.py'),'predeclared_controls':s['forcing_cases'],'no_historical_grid_yet':True,'current_stage':'static_input_preparation_no_solver_runs','new_people_counts':False,'training':False,'sealed_tests':False,'accuracy_claim':'Requires independent outcome evidence; paired differences alone do not establish improvement.'};dump(P/'common_evaluation_contract.json',contract)
 summary={**s,'status':'paired_inputs_built_and_statically_validated','tables_built':True,'static_validation_checks':len(val['checks']),'input_bundles':8,'actual_solver_runs':0,'runtime_qualified':False,'static_results_are_not_flood_simulation_results':True,'prepared_T_template_receipt':'data/processed/three_ward_urban_geometry_pair_inputs_v1/terrain_template/table_build_receipt.json','next_execution':'First dry_raised matched pair, then rain60_raised pair if original numerical gates pass; remaining two controls stay queued. Existing U responses may be reused only after full identity/input/output equivalence audit.'};dump(R/'summary.json',summary)
 links=[P/'prepared_run_manifest.json',P/'common_evaluation_contract.json',P/'reference_policy_binding.json',P/'source_bindings.json',P/'terrain_template/table_build_receipt.json',R/'actual_encoded_pair_volumes.csv',R/'table_interface_summary.csv',R/'validation.json',R/'summary.json']
 def link(p):return '<a href="'+os.path.relpath(p,R)+'">'+html.escape(p.name)+'</a>'
 body=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>三区城市几何对照 · 配对输入已准备</title><style>body{{margin:0;background:#f2f5f7;color:#253b48;font:16px/1.8 system-ui,-apple-system,sans-serif}}main{{max-width:1120px;margin:auto;padding:36px 24px 70px}}h1{{font-size:32px;line-height:1.4}}h2{{font-size:23px}}section,.notice{{padding:22px 26px;margin:22px 0;background:#fff;border:1px solid #dce4e9;border-radius:10px}}.notice{{border-left:5px solid #c98043;background:#fff8e9}}.kpis{{display:flex;gap:15px;flex-wrap:wrap}}.kpis div{{background:#e7eff4;flex:1;min-width:170px;padding:17px;border-radius:8px}}.big{{display:block;font-weight:bold;font-size:27px}}table{{border-collapse:collapse;width:100%;font-size:14px}}td,th{{text-align:left;padding:10px 12px;border-bottom:1px solid #dde5ea;vertical-align:top}}th{{background:#eef3f6}}.scroll{{overflow:auto}}img{{max-width:100%}}a{{color:#17698f}}.small{{font-size:13px;color:#557080}}li{{margin:7px 0}}code{{font-size:13px;background:#eef2f4}}</style><main><p class="small">UDT01b · 2026-10-16 · WHOLE THREE WARDS</p><h1>三维城市信息有什么作用？<br>先建立公平的“仅地形—城市几何”对照</h1><p>已构建全域10 m仅地形输入、重新生成储水与过流表，并准备四个既有控制事件的T/U配对输入。原始地形、已完成结果、正式12＋4划分及人口不确定性保持不变。</p><div class="notice"><b>本次完成的是可运行输入与静态接口核验，新增水动力运行0次。</b><p>还没有两组新的配对模拟结果，因此不能报告城市几何减少了多少积水、改善了多少交通连接。历史降雨数值格网仍未取得，当前控制事件属于合成情景，不是历史复现。</p></div><div class="kpis"><div><span class="big">38.9768 km²</span>两组相同物理降雨汇水范围</div><div><span class="big">13.0406 km²</span>城市组建筑占地／屋面雨量来源</div><div><span class="big">31,384</span>仅地形组恢复的10 m网格</div><div><span class="big">8套 / 0次</span>配对输入／本次水动力运行</div></div>
<section><h2>1. 这项对照识别什么</h2><p>在同一暴雨、河道边界、地形来源和数值配置下，比较加入建筑阻水、道路糙率、格面连通及屋面雨量分配后，三区积水暴露与交通暴露判断改变多少。这是现有城市几何组合的贡献检验，不能分离每个因素，也不能证明CityGML格式本身优于含同等信息的二维数据。</p>{table(['项目','T：仅地形','U：加入城市几何'],[['基础地形','同一官方0.50 m采样地形与PLATEAU补缺；原文件未修改','相同地形来源，非建筑区域的障碍地形差为0'],['建筑','恢复原汇水范围的建筑占地地形和储水空间','保留现有建筑阻水与封闭面；+10 m是障碍假设，并非逐楼真实高度'],['道路与格面','背景Manning n=0.04，原始地形格面','现有地面道路n=0.03、背景n=0.04，保留约束；边界条带保持原配置'],['降雨','整个原汇水范围均匀承接物理降雨','开放地面直接降雨＋屋面雨量即时保守分配；两组总雨量相同'],['网格与求解器','10 m固定格网、253层子网格表、同一已绑定CPU求解器','同一格网与求解器；有效单元、格面及储水体积允许随建筑改变']])}<p class="small">PLATEAU道路桥梁／地下分层在现有地表水力输入中仍有未解析部分，本次不补造立体水流连接。交通网络中的垂直通行关系需要独立证据。</p></section>
<section><h2>2. 输入核验结果</h2><p>扫描了原始细地形，恢复单元及全部活动单元内缺测样本为0。T有400,256个活动单元，U有368,872个；10,488个规定水位单元位置完全相同。两组的有效单元数量不同是建筑处理的结果，不通过删掉T的建筑占地储水来强行配平。</p>{table(['组别','活动单元','原生格面','子网格层数'],[[q['arm'],q['native_cells'],q['native_faces'],q['levels']] for q in tt])}<p>T生成了自己的原生索引、相邻格面、每个单元的诊断元数据及7,318个地表—规定水位交界断面；没有直接移植U的原生编号。两组水位序列与点序相同，交界面数量可以因新增地面单元而改变。静态表检查覆盖有限值、储水曲线单调性、湿面积比例及正糙率。</p><img src="urban_information_support.png" alt="Whole-domain building and road input support"><p class="small">此图仅显示建筑与道路信息覆盖，不能视为积水或孤岛结果。共同开放地表25.9362 km²，地面道路支持9.0369 km²；范围包括现有必要跨区地面汇水部分，其外边界完整性尚未经过地理认证。</p></section>
<section><h2>3. 同样的雨，两种空间分配</h2><p>保留四个既有控制的原雨型、秒级时刻和七组水位序列。逐个读取实际导出的NetCDF降雨，按各自活动地面计算总施加体积；未以理想权重总和代替文件检查。</p>{table(['控制事件','物理累计雨量 mm','共同汇水范围 m²','T编码雨量 m³','U编码雨量 m³','U−T m³'],[[q['case_id'],q['physical_rain_depth_mm'],q['physical_catchment_m2'],f"{float(q['terrain_encoded_m3']):.6f}",f"{float(q['urban_encoded_m3']):.6f}",f"{float(q['urban_minus_terrain_m3']):.6f}"] for q in vols])}<p>全部通过原1×10⁻⁶相对雨量门槛。两个降雨开始／结束拐点保留秒级信息；编码体积一致不代表求解器已经正确施加，实际同一步雨量预算仍需运行后核验。这四个控制同属CONTROL-LEGACY，不增加独立父事件数量。</p></section>
<section><h2>4. 后续怎样评价城市几何的意义</h2>{table(['问题','配对指标与限制'],[['积水区是否改变','在同一原始开放细地表上重建峰值水深；比较0.10/0.30/0.50 m超阈值面积、增加／减少湿区、深度差及固定片区排序。结果称为差异或一致性，不直接称准确率提升。'],['道路暴露是否改变','使用同一地面道路支持，比较受影响地表面积与水深。道路面积不替代道路长度，也不直接等于关闭路段。'],['车站暴露是否改变','使用同一站口点及20 m邻域，比较暴露面积和排序；保留站口归属未知，不从暴露直接推断地下进水或真实停运。'],['水量是否守恒','分别纳入全部原生地面单元，保留T建筑占地的虚拟地面储量；核验同一步雨量、实际时钟、正性以及完整双向边界交换。'],['质量掩膜是否公平','每组按原政策生成自己的隔离区与区间标签，再取共同可用支持；不复制U结果掩膜给T，不取区间中点，不用掩膜救回数值失败事件。'],['地表排水路径是否改变','峰值水深图不能证明方向或真实流量路径；内部累计格面交换尚未核验，暂不报告路径精度。']])}</section>
<section><h2>5. 运行顺序与证据边界</h2><p>下一执行批次先做干控制配对，核验边界与新索引，再做60 mm/h加水位抬升的降雨配对；通过原门槛后才扩至另外两项控制。已有U结果只有在完整输入、源码／镜像、实际时钟及输出合同一致时才能复用，文件存在本身不构成复用资格。</p><p>本次没有调用求解器，也没有开始训练、打开封存测试或计算受困人数。历史雷达／格点降雨是独立待补的数据分支；它用于约束输入雨场，积水与交通后果的准确性仍需独立观测核验。</p><ul>{''.join('<li>'+link(p)+'</li>' for p in links)}</ul><p class="small">复现：用现有HydroMT-SFINCS1.2.2构建环境运行prepare_urban_geometry_pair_inputs_v1.py --build-tables，再运行finalize_urban_geometry_pair_inputs_v1.py；项目环境运行本报告脚本。原方案MILI-D-20261016-013保留，未改写旧方案或AnaSOP。源代码和所有交付文件的哈希见delivery_manifest.json。</p></section></main></html>'''
 (R/'review.html').write_text(body)
 scripts=[ROOT/'src/preprocessing/prepare_urban_geometry_pair_inputs_v1.py',ROOT/'src/analyses/finalize_urban_geometry_pair_inputs_v1.py',Path(__file__).resolve()]
 # Hash large hardlinks only once per inode; include every path in manifest.
 cache={};items=[]
 for f in sorted(P.rglob('*'))+sorted(R.glob('*'))+scripts:
  if not f.is_file() or f.name in ['delivery_manifest.json','delivery_validation.json']:continue
  st=f.stat();key=(st.st_dev,st.st_ino)
  if key not in cache:cache[key]=sha(f)
  items.append({'file':str(f.relative_to(ROOT)),'sha256':cache[key],'bytes':st.st_size})
 dump(R/'delivery_manifest.json',{'artifacts':items,'hydraulic_runs':0,'static_inputs_only':True,'original_population_and_model_outputs_unchanged':True})
 broken=[]
 import re
 for value in re.findall(r'(?:src|href)="([^"]+)"',body):
  if '://' not in value and not (R/value).resolve().is_file():broken.append(value)
 dump(R/'delivery_validation.json',{'all_passed':val['all_passed'] and not broken,'static_check_count':len(val['checks']),'broken_links':broken,'image_generated':(R/'urban_information_support.png').is_file(),'solver_runs':0,'interpretation':'Ready static inputs; runtime and outcome comparison pending.'});assert not broken
 print('REPORT COMPLETE',R/'review.html',flush=True)
if __name__=='__main__':main()
